function trier_tableau(arr) {
  const n = arr.length;
  if (n <= 1) return arr.slice();
  const aux = new Array(n);
  for (let width = 1; width < n; width *= 2) {
    for (let left = 0; left < n; left += 2 * width) {
      let low = left, mid = Math.min(left + width, n), high = Math.min(left + 2 * width, n);
      let i = low, j = mid, k = low;
      while (i < mid && j < high) {
        if (arr[i] <= arr[j]) aux[k++] = arr[i++];
        else aux[k++] = arr[j++];
      }
      while (i < mid) aux[k++] = arr[i++];
      while (j < high) aux[k++] = arr[j++];
      for (let p = low; p < high; p++) arr[p] = aux[p];
    }
  }
  return arr.slice(); // tri stable O(N log N), sans .sort()
}
