        if (result.length === 0 || result[result.length - 1][1] < start) {
            result.push([start, sorted[i][1]]);
        } else {
            result[result.length - 1][1] = Math.max(result[result.length - 1][1], sorted[i][1]);
        }
    }
    return result;
}
