### algo_difficile_1
> Approche par recherche binaire sur le tableau le plus court, comme indiqué dans l'indice du professeur : complexité O(log(min(n, m))). On partitionne les deux tableaux de façon équilibrée.
```javascript
function medianeDeuxTries(a, b) {
    // Binaire sur le plus petit tableau pour garantir O(log(min(m, n)))
    if (a.length > b.length) {
        const temp = a; a = b; b = temp;
    }

    const m = a.length;
    const n = b.length;
    let low = 0;
    let high = m;

    while (low <= high) {
        const partitionA = Math.floor((low + high) / 2);
        const partitionB = Math.floor((m + n + 1) / 2) - partitionA;

        const maxLeftA = a[partitionA - 1] !== undefined ? a[partitionA - 1] : -Infinity;
        const minRightA = a[partitionA] !== undefined ? a[partitionA] : Infinity;
        const maxLeftB = b[partitionB - 1] !== undefined ? b[partitionB - 1] : -Infinity;
        const minRightB = b[partitionB] !== undefined ? b[partitionB] : Infinity;

        if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
            // Partition correcte trouvée.
            return (m + n) % 2 === 0
                ? (Math.max(maxLeftA, maxLeftB) + Math.min(minRightA, minRightB)) / 2
                : Math.max(maxLeftA, maxLeftB);
        } else if (maxLeftA > minRightB) {
            high = partitionA - 1;
        } else {
            low = partitionA + 1;
        }
    }

    throw new Error("Entrée invalide");
}
```

### algo_defi
```javascript
function plusLongueSousSuiteCroissante(tab) {
    const n = tab.length;
    if (n === 0) return 0;

    // DP O(n^2) : dp[i] = longueur de la sous-suite strictement croissante terminée en tab[i].
    const dp = new Array(n).fill(1);
    let best = 1;
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (tab[j] < tab[i]) { // strictement croissante
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        best = Math.max(best, dp[i]);
    }
    return best;
}
```

